"""Helpers shared by the case modules: one vector = input → model → projected expectation."""

from __future__ import annotations

import json

from lessdugin_ref.fold import fold_vector_input
from lessdugin_ref.projections import project

GENERATED_BY = "Generated by testdata/vectors/social-ref/gen_social.py from the reference model; do not edit."


def vector(kind: str, name: str, fold_input: dict, *, fields=None, query=None, note=None,
           invalid=None, expect=None) -> dict:
    """Build one vector.

    invalid: {uri: rule} — the records that are deliberately invalid, with their first failing
             rule; every other record must be valid, and the note must name each rule.
    expect:  optional {field: value} sanity checks against the model's own output (hand-derived
             expectations written in the case module, so that a model regression is caught).
    """
    inp = {"fold": fold_input}
    if query is not None:
        inp["query"] = query
    inp = json.loads(json.dumps(inp))            # the model reads exactly what is written
    view = fold_vector_input(inp)
    invalid = invalid or {}
    for u, v in view.validity.items():
        if u in invalid:
            assert not v.valid and v.rule == invalid[u], (name, u, v, invalid[u])
            assert note and invalid[u] in note, f"{name}: the note must name rule {invalid[u]}"
        else:
            assert v.valid, (name, u, v)
    expected = project(view, kind, fields)
    if expect:
        for k, want in expect.items():
            got = expected[k] if k in expected else project(view, kind, [k])[k]
            assert got == want, f"{name}: {k}\n  model: {got}\n  hand:  {want}"
    out = {"name": name, "input": inp, "expected": expected}
    if note:
        out["note"] = note
    return out


def file_doc(behaviour: str, kind: str, description: str, vectors: list, **extra) -> dict:
    names = [v["name"] for v in vectors]
    assert len(names) == len(set(names)), "vector names must be unique within a file"
    return {"behaviour": behaviour, "kind": kind, "description": description + " " + GENERATED_BY,
            "vectors": vectors, **extra}
